    ; Update pato 1 - Patrol bounce
    ; Waypoints: (96, 160) -> (144, 160)
    ld e, 1             ; Entity index
    ld d, 0

    ; --- X axis bounce ---
    ld hl, entity_vel_x
    add hl, de
    ld a, (hl)
    or a
    jp z, .patrol_end_1
    bit 7, a
    jp nz, .patrol_chk_min_x_1

    ; Moving right: x >= 144?
    ld hl, entity_x_pos
    add hl, de
    ld a, (hl)
    cp 144
    jp c, .patrol_end_1
    ; Bounce: negate vel_x
    ld hl, entity_vel_x
    add hl, de
    ld a, (hl)
    neg
    ld (hl), a
    jp .patrol_end_1

