    ; East exit: X near right edge and rightward input
    ld a, (input_state)
    cp STICK_RIGHT
    jr z, .dir_ok_check_transition_worldmap_1770754170935_s0_skip_east
    cp STICK_UPRIGHT
    jr z, .dir_ok_check_transition_worldmap_1770754170935_s0_skip_east
    cp STICK_DOWNRIGHT
